 * Column/row helpers shared by the sheet parser, the formula evaluator and
 * the deps walker: converting between the letters/digits spelling of an
 * address and the numeric column index used for sorting, and deciding
 * whether a piece of address-shaped text names a cell in range.
 */

export function colIndex(letters) {
  const s = letters.toUpperCase()
  if (s.length === 1) return s.charCodeAt(0) - 64
  return 26 + (s.charCodeAt(0) - 65) * 26 + (s.charCodeAt(1) - 64)
}

export function indexToCol(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const rem = n - 26
  const first = Math.floor((rem - 1) / 26)
  const second = (rem - 1) % 26
  return String.fromCharCode(65 + first) + String.fromCharCode(65 + second)
}

/**
 * Resolves address-shaped text (letters followed by digits, possibly the
 * wrong number of either) to its canonical form when it names a cell inside
 * the addressable range, or reports that it does not.
 */
export function resolveAddressText(text) {
  const m = /^([A-Za-z]+)(\d*)$/.exec(text)
  if (!m) return { inRange: false }
  const letters = m[1]
  const digits = m[2]
  if (letters.length < 1 || letters.length > 2) return { inRange: false }
  if (digits.length < 1 || digits.length > 3) return { inRange: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { inRange: false }
  const col = letters.toUpperCase()
  return { inRange: true, col, row, canonical: col + String(row) }
}
"}

