 * Turns the text of a formula (everything after the leading `=`) into a
 * token stream for the parser. Spaces and tabs are skipped; any other
 * character that starts no valid token is a lexing failure, which the
 * parser reports the same way as any other grammar failure.
 */

const SIMPLE_OPS = '^*/+-=<>():,'

export class LexError extends Error {}

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const c = src[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.' && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUM', value: src.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(src[j])) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'WORD', value: src.slice(i, j) })
      i = j
      continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: two, value: two })
      i += 2
      continue
    }
    if (SIMPLE_OPS.includes(c)) {
      tokens.push({ type: c, value: c })
      i++
      continue
    }
    throw new LexError(`unexpected character ${c}`)
  }
  return tokens
}
"}

