{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-OhMZ1x/src/parser.js","content":"/**
 * Recursive-descent parser for the formula grammar. Precedence, tightest
 * first: a leading `+`/`-`, then `^` (right associative), then `*`/`/`,
 * then `+`/`-`, then the comparisons; all but `^` group to the left. A
 * range (`A1:B3`) is only accepted directly as a function argument.
 */

import { tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  parse() {
    const node = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return node
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && COMPARE_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && (this.peek().type === '+' || this.peek().type === '-')) {
      const op = this.next().type
      const right = this.parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && (this.peek().type === '*' || this.peek().type === '/')) {
      const op = this.next().type
      const right = this.parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek() && (this.peek().type === '+' || this.peek().type === '-')) {
      const op = this.next().type
      const node = this.parseUnary()
      return { type: 'unary', op, node }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUM') {
      this.next()
      return { type: 'num', value: Number(t.value) }
    }
    if (t.type === 'WORD') {
      this.next()
      if (this.peek() && this.peek().type === '(') {
        this.next()
        const args = []
        if (!(this.peek() && this.peek().type === ')')) {
          args.push(this.parseArg())
          while (this.peek() && this.peek().type === ',') {
            this.next()
            args.push(this.parseArg())
          }
        }
        this.expect(')')
        return { type: 'call', name: t.value, args }
      }
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'addr', text: t.value }
    }
    if (t.type === '(') {
      this.next()
      const node = this.parseComparison()
      this.expect(')')
      return node
    }
    throw new ParseError('unexpected token')
  }

  parseArg() {
    if (this.peek() && this.peek().type === 'WORD' && this.peek(1) && this.peek(1).type === ':') {
      const a = this.next().value
      this.next() // ':'
      const bTok = this.peek()
      if (!bTok || bTok.type !== 'WORD') throw new ParseError('expected address after :')
      this.next()
      return { type: 'range', a, b: bTok.value }
    }
    return this.parseComparison()
  }
}

export function parseFormula(text) {
  const tokens = tokenize(text)
  const parser = new Parser(tokens)
  return parser.parse()
}
"}

