 * Parses the sheet text read from standard input into a map from canonical
 * address to declared cell, enforcing the address syntax and rejecting
 * duplicate declarations.
 */

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const ADDRESS_RE = /^([A-Za-z]{1,2})(\d{1,3})$/

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    let line = lines[i]
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    line = line.slice(j)
    if (line === '' || line[0] === '#') continue

    let k = 0
    while (k < line.length && line[k] !== ' ' && line[k] !== '\t') k++
    const addrText = line.slice(0, k)
    const rest = line.slice(k)
    let m = 0
    while (m < rest.length && (rest[m] === ' ' || rest[m] === '\t')) m++
    const content = rest.slice(m)

    const match = ADDRESS_RE.exec(addrText)
    const row = match ? parseInt(match[2], 10) : 0
    if (!match || row < 1) {
      throw new SheetError(lineNo, `invalid cell address ${addrText}`)
    }
    const col = match[1].toUpperCase()
    const canonical = col + String(row)
    if (cells.has(canonical)) {
      throw new SheetError(lineNo, `cell ${canonical} is declared twice`)
    }
    cells.set(canonical, { col, row, text: content })
  }

  return cells
}
"}

