 * Formats an evaluated cell value for `values` output: numbers are rounded
 * to ten significant digits and printed the way JavaScript would print
 * them, booleans print as TRUE/FALSE, and text and errors print as-is.
 */

export function roundSignificant(x, digits) {
  if (x === 0) return 0
  const sign = x < 0 ? -1 : 1
  const abs = Math.abs(x)
  const magnitude = Math.floor(Math.log10(abs))
  const factor = Math.pow(10, digits - 1 - magnitude)
  const rounded = Math.round(abs * factor) / factor
  return sign * rounded
}

export function formatValue(value) {
  switch (value.t) {
    case 'number':
      return String(roundSignificant(value.v, 10))
    case 'text':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'error':
      return value.v
    default:
      throw new Error(`unknown value type ${value.t}`)
  }
}
"}

