  if (v.t === 'error') return v
  if (v.t === 'number') return v
  if (v.t === 'bool') return { t: 'number', v: v.v ? 1 : 0 }
  return { t: 'error', v: '#VALUE!' }
}

function finiteNum(x) {
  if (!Number.isFinite(x)) return { t: 'error', v: '#DIV/0!' }
  return { t: 'number', v: x }
}

function compareValues(a, b) {
  const rank = { number: 0, text: 1, bool: 2 }
  if (rank[a.t] !== rank[b.t]) return rank[a.t] - rank[b.t]
  if (a.t === 'number') return a.v - b.v
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

export function evaluateSheet(cells) {
  const parsedCache = new Map()
  for (const [addr, cell] of cells) {
    if (cell.text.startsWith('=')) {
      let ast = null
      try {
        ast = parseFormula(cell.text.slice(1))
      } catch {
        ast = null
      }
      parsedCache.set(addr, { kind: 'formula', ast })
    } else {
      parsedCache.set(addr, { kind: 'literal', value: parseLiteral(cell.text) })
    }
  }

  const memo = new Map()
  const computing = new Set()

  function evalCell(addr) {
    if (memo.has(addr)) return memo.get(addr)
    if (computing.has(addr)) return { t: 'error', v: '#CYCLE!' }

    const parsed = parsedCache.get(addr)
    if (!parsed) {
      const v = { t: 'number', v: 0 }
      memo.set(addr, v)
      return v
    }
    if (parsed.kind === 'literal') {
      memo.set(addr, parsed.value)
      return parsed.value
    }

    computing.add(addr)
    const result = parsed.ast ? evalNode(parsed.ast) : { t: 'error', v: '#ERR!' }
    computing.delete(addr)
    memo.set(addr, result)
    return result
  }

  function evalAddressNode(text) {
    const r = resolveAddressText(text)
    if (!r.inRange) return { t: 'error', v: '#REF!' }
    return evalCell(r.canonical)
  }

  function evalRangeValues(a, b) {
    const ra = resolveAddressText(a)
    const rb = resolveAddressText(b)
    if (!ra.inRange || !rb.inRange) return [{ t: 'error', v: '#REF!' }]
    const c1 = colIndex(ra.col)
    const c2 = colIndex(rb.col)
    const cMin = Math.min(c1, c2)
    const cMax = Math.max(c1, c2)
    const rMin = Math.min(ra.row, rb.row)
    const rMax = Math.max(ra.row, rb.row)
    const values = []
    for (let c = cMin; c <= cMax; c++) {
      const colLetters = indexToCol(c)
      for (let r = rMin; r <= rMax; r++) {
        values.push(evalCell(colLetters + r))
      }
    }
    return values
  }

  function evalArgSlot(node) {
    if (node.type === 'range') return evalRangeValues(node.a, node.b)
    return [evalNode(node)]
  }

  function arith(op, l, r) {
    const lc = toNumber(l)
    if (lc.t === 'error') return lc
    const rc = toNumber(r)
    if (rc.t === 'error') return rc
    let res
    switch (op) {
      case '+':
        res = lc.v + rc.v
        break
      case '-':
        res = lc.v - rc.v
        break
      case '*':
        res = lc.v * rc.v
        break
      case '/':
        res = lc.v / rc.v
        break
      case '^':
        res = Math.pow(lc.v, rc.v)
        break
    }
    return finiteNum(res)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return { t: 'number', v: node.value }
      case 'bool':
        return { t: 'bool', v: node.value }
      case 'addr':
        return evalAddressNode(node.text)
      case 'range':
        // A range can only reach here through a defensive path; the parser
        // never places one outside a function argument.
        return { t: 'error', v: '#ERR!' }
      case 'unary': {
        const v = toNumber(evalNode(node.node))
        if (v.t === 'error') return v
        return finiteNum(node.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = evalNode(node.left)
        const r = evalNode(node.right)
        if (ARITH_OPS.has(node.op)) return arith(node.op, l, r)
        if (l.t === 'error') return l
        if (r.t === 'error') return r
        const c = compareValues(l, r)
        let res
        switch (node.op) {
          case '=':
            res = c === 0
            break
          case '<>':
            res = c !== 0
            break
          case '<':
            res = c < 0
            break
          case '<=':
            res = c <= 0
            break
          case '>':
            res = c > 0
            break
          case '>=':
            res = c >= 0
            break
        }
        return { t: 'bool', v: res }
      }
      case 'call':
        return evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  function evalCall(node) {
    const name = node.name.toUpperCase()
    const spec = FUNCS[name]
    if (!spec) return { t: 'error', v: '#NAME?' }
    if (node.args.length < spec.min || node.args.length > spec.max) {
      return { t: 'error', v: '#ERR!' }
    }

    if (name === 'IF') {
      const condList = evalArgSlot(node.args[0])
      for (const v of condList) if (v.t === 'error') return v
      const condNum = toNumber(condList[0])
      if (condNum.t === 'error') return condNum
      const branch = condNum.v !== 0 ? node.args[1] : node.args[2]
      const list = evalArgSlot(branch)
      for (const v of list) if (v.t === 'error') return v
      return list[0]
    }

    let values = []
    for (const arg of node.args) values = values.concat(evalArgSlot(arg))

    if (name === 'COUNT') {
      for (const v of values) if (v.t === 'error') return v
      let count = 0
      for (const v of values) if (v.t === 'number') count++
      return { t: 'number', v: count }
    }

    if (name === 'ABS') {
      const n = toNumber(values[0])
      if (n.t === 'error') return n
      return finiteNum(Math.abs(n.v))
    }

    const nums = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.t === 'error') return n
      nums.push(n.v)
    }
    if (name === 'SUM') return finiteNum(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return finiteNum(nums.reduce((a, b) => Math.min(a, b)))
    if (name === 'MAX') return finiteNum(nums.reduce((a, b) => Math.max(a, b)))
    if (name === 'AVG') return finiteNum(nums.reduce((a, b) => a + b, 0) / nums.length)
    throw new Error(`unhandled function ${name}`)
  }

  const results = new Map()
  for (const addr of cells.keys()) {
    results.set(addr, evalCell(addr))
  }
  return results
}
"}

