import { parseFormula } from './parser.js'
import { evaluateSheet } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { colIndex } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const sortedAddrs = [...cells.keys()].sort((a, b) => {
    const ca = cells.get(a)
    const cb = cells.get(b)
    return colIndex(ca.col) - colIndex(cb.col) || ca.row - cb.row
  })

  let out = ''
  if (mode === 'values') {
    const results = evaluateSheet(cells)
    for (const addr of sortedAddrs) {
      out += `${addr}=${formatValue(results.get(addr))}\n`
    }
  } else {
    for (const addr of sortedAddrs) {
      const cell = cells.get(addr)
      let deps = []
      if (cell.text.startsWith('=')) {
        let ast = null
        try {
          ast = parseFormula(cell.text.slice(1))
        } catch {
          ast = null
        }
        if (ast) deps = collectDeps(ast)
      }
      out += `${addr}:${deps.length ? ' ' + deps.join(' ') : ''}\n`
    }
  }
  process.stdout.write(out)
}

main()
"}

